<?php
declare(strict_types=1);
$reportData = (array) ($billingContext['data']['report'] ?? []); $dataset = (array) ($reportData['dataset'] ?? []); $rows = (array) ($dataset['rows'] ?? []); $selected = (string) ($reportData['report'] ?? 'payments');
?>
<div data-billing-reports><div class="portal-card-head"><div><strong>Billing hesabatlari</strong><small>Yalniz Billing domenine aid odenis, musteri, xidmet, paket ve provider xulaseleri.</small></div></div><form class="billing-filter is-wide" method="get" action="billing-reports.php" data-billing-filter><div class="portal-form-row"><label>Hesabat</label><select name="report"><?php foreach (['payments'=>'Odenisler','customers'=>'Musteriler','services'=>'Xidmetler','packages'=>'Paketler','providers'=>'Providerler'] as $key=>$label): ?><option value="<?= e($key); ?>"<?= $selected === $key ? ' selected' : ''; ?>><?= e($label); ?></option><?php endforeach; ?></select></div><div class="portal-form-row"><label>Tarix araligi</label><select name="range"><?php foreach (['today'=>'Bugun','yesterday'=>'Dunen','week'=>'Son 1 hefte','month'=>'Son 1 ay','year'=>'Son 1 il','custom'=>'Secilmis tarix'] as $key=>$label): ?><option value="<?= e($key); ?>"<?= ($reportData['range'] ?? '') === $key ? ' selected' : ''; ?>><?= e($label); ?></option><?php endforeach; ?></select></div><div class="portal-form-row"><label>Ilkin tarix</label><input type="date" name="start_date" value="<?= e((string) ($reportData['start_date'] ?? '')); ?>"></div><div class="portal-form-row"><label>Son tarix</label><input type="date" name="end_date" value="<?= e((string) ($reportData['end_date'] ?? '')); ?>"></div><button class="portal-primary-btn" type="submit">Yenile</button></form><div class="portal-table-wrap"><table class="portal-table"><thead><tr><th>Bolme</th><th>Deyer</th><th>Qeyd sayi</th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr data-billing-row><td><strong><?= e((string) ($row['label'] ?? '-')); ?></strong></td><td><?= e(number_format((float) ($row['value'] ?? 0), 2, '.', ' ')); ?><?= ($dataset['kind'] ?? '') === 'money' ? ' AZN' : ''; ?></td><td><?= e((string) ($row['count'] ?? 0)); ?></td></tr><?php endforeach; ?><?php if ($rows === []): ?><tr><td colspan="3" class="billing-empty">Secilmis dovr uzre hesabat melumati yoxdur.</td></tr><?php endif; ?></tbody></table></div></div>
